/**
 * Story chapters 2–10 of Escape from Tarkov 1.0+ (stages in the in-game order) and map points for Tour.
 * GENERATED from szepiz/tarkov-quest-data `mapdata/story.json` (baked 2026-08-11): the chapter/objective list comes from
 * tarkovtracker-org/tarkov-data-overlay `src/additions/storyChapters.json5` (MIT; captured from the game client + EFT wiki),
 * the map points were placed by hand against the game (CC0, as of 2026-08-16). `synthetic` stages were added by that
 * project from the wiki (not seen in the client capture). The overlay marks every chapter except Tour, Falling Skies and
 * Batya as partial: a missing stage is possible.
 * Russian text is our own translation (not the official client wording). Regenerate with
 * scratchpad research/gen-story.cjs; research notes: scratchpad research/story-quests.md.
 * Point coordinates: game x/z (tarkov.dev space); `outline` is an area [x, z][] and x/z its centre.
 */
export interface StoryStagePointSeed { mapId: string; x: number; z: number; outline?: Array<[number, number]> }
export interface StoryText { ru: string; en: string }
export interface StoryStageSeed extends StoryText {
  mapIds: string[]
  optional?: boolean
  /** Ending branch the stage belongs to (EN text of the branch header). */
  branch?: string
  steps?: Array<StoryText & { optional?: boolean }>
  needs?: string
  points?: StoryStagePointSeed[]
  synthetic?: boolean
}
export interface StoryChapterSeed { id: string; order: number; en: string; ru: string; aliases: string[]; requires: string[]; stages: StoryStageSeed[] }

